/**
 * osm-overpass — building footprints, street centrelines and POIs from OpenStreetMap.
 *
 * This adapter closes the repo's single worst reproducibility hole. Today
 * union-square-sf/tools/geo/build_gis.mjs reads `src/data/recon/osm_raw.json`, and
 * that file is in .gitignore — so the committed gis.json cannot be regenerated by
 * anyone who clones the repo, and kyoto-higashiyama has no fetch step at all (its
 * geo.json is a committed artefact with no producer). After this, one command
 * rebuilds either world's geometry from scratch.
 */
import { fetchCached } from '../http.mjs';

const ENDPOINTS = [
  'https://overpass-api.de/api/interpreter',
  'https://overpass.kumi.systems/api/interpreter',
];

/** Build the Overpass QL for a bbox. `out body geom` gives us node coords inline. */
function query(bbox, { timeoutS = 180 }) {
  const b = `${bbox.south},${bbox.west},${bbox.north},${bbox.east}`;
  return `[out:json][timeout:${timeoutS}];
(
  way["building"](${b});
  relation["building"](${b});
  way["building:part"](${b});
  way["highway"](${b});
  way["railway"](${b});
  way["footway"](${b});
  way["barrier"](${b});
  way["natural"](${b});
  way["waterway"](${b});
  way["leisure"](${b});
  way["historic"](${b});
  way["man_made"](${b});
  node["shop"](${b});
  node["amenity"](${b});
  node["tourism"](${b});
  node["office"](${b});
  node["highway"="traffic_signals"](${b});
  node["highway"="street_lamp"](${b});
  node["natural"="tree"](${b});
  node["public_transport"](${b});
  node["historic"](${b});
);
out body geom;`;
}

const LEVEL_HEIGHT_M = 3.6; // fallback storey height when only building:levels is tagged

/** Parse OSM's messy height strings: "25.9", "25.9 m", "85'" (feet). */
function parseHeight(raw) {
  if (raw == null) return null;
  const s = String(raw).trim();
  const feet = s.match(/^([\d.]+)\s*'$/);
  if (feet) return Number(feet[1]) * 0.3048;
  const m = s.match(/^([\d.]+)/);
  return m ? Number(m[1]) : null;
}

export default {
  id: 'osm-overpass',
  title: 'OpenStreetMap via the Overpass API',
  license: 'ODbL-1.0',
  attribution: '© OpenStreetMap contributors',
  homepage: 'https://www.openstreetmap.org/copyright',
  requires: [],
  provides: ['buildings', 'streets', 'pois', 'landmarks'],

  async fetch(ctx) {
    const ql = query(ctx.world.bbox, ctx.options ?? {});
    let lastErr;
    for (const endpoint of ENDPOINTS) {
      try {
        const r = await fetchCached(endpoint, {
          method: 'POST',
          body: `data=${encodeURIComponent(ql)}`,
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          cacheDir: ctx.cacheDir,
          maxAgeMs: ctx.maxAgeMs,
          refresh: ctx.refresh,
          timeoutMs: 240_000,
        });
        return { raw: JSON.parse(r.body), provenance: r.provenance, fromCache: r.fromCache };
      } catch (err) {
        lastErr = err;
        ctx.log?.(`overpass endpoint ${endpoint} failed: ${err.message}`);
      }
    }
    throw new Error(`all Overpass endpoints failed: ${lastErr?.message}`);
  },

  normalize(raw, ctx) {
    const { frame, world } = ctx;
    const elements = raw.elements ?? [];
    const buildings = [];
    const buildingParts = [];
    const streets = [];
    const pois = [];

    // Overpass returns relation members with their own geometry under `members`;
    // for a multipolygon building the outer ways are what we want.
    const ringsOf = (el) => {
      if (el.geometry) return [el.geometry];
      if (el.members) return el.members.filter((m) => m.role === 'outer' && m.geometry).map((m) => m.geometry);
      return [];
    };

    for (const el of elements) {
      const tags = el.tags ?? {};
      const id = `${el.type}/${el.id}`;

      if (tags.building || tags['building:part']) {
        for (const geom of ringsOf(el)) {
          if (geom.length < 4) continue;
          const footprint = geom.map((p) => {
            const l = frame.geoToLocal(p.lat, p.lon);
            return [round2(l.x), round2(l.z)];
          });
          const centroidGeo = ringCentroid(geom);
          if (!frame.inBbox(world.bbox, centroidGeo.lat, centroidGeo.lon, ctx.marginM ?? 60)) continue;
          const levels = tags['building:levels'] ? Number(tags['building:levels']) : null;
          const rec = {
            id,
            footprint,
            // The lat/lon ring, kept alongside the projected footprint so sources
            // that sample geospatial rasters or point clouds (usgs-lidar-lpc) can
            // reproject it themselves without inverting our local frame.
            ringGeo: geom.map((p) => [p.lon, p.lat]),
            centroidGeo,
            heightM: parseHeight(tags.height) ?? (levels ? levels * LEVEL_HEIGHT_M : null),
            heightSource: tags.height ? 'osm:height' : levels ? 'osm:building:levels' : null,
            levels,
            name: tags.name ?? null,
            tags,
          };
          (tags['building:part'] && !tags.building ? buildingParts : buildings).push(rec);
        }
        continue;
      }

      if (el.geometry && (tags.highway || tags.railway || tags.footway || tags.waterway)) {
        const points = el.geometry
          .filter((p) => frame.inBbox(world.bbox, p.lat, p.lon, ctx.marginM ?? 60))
          .map((p) => {
            const l = frame.geoToLocal(p.lat, p.lon);
            return [round2(l.x), round2(l.z)];
          });
        if (points.length >= 2) {
          streets.push({
            id,
            points,
            kind: tags.highway ?? tags.railway ?? tags.waterway ?? 'path',
            name: tags.name ?? null,
            lanes: tags.lanes ? Number(tags.lanes) : null,
            widthM: tags.width ? parseHeight(tags.width) : null,
            oneway: tags.oneway === 'yes',
            tags,
          });
        }
        continue;
      }

      if (el.type === 'node' && (tags.shop || tags.amenity || tags.tourism || tags.office || tags.public_transport || tags.historic)) {
        if (!frame.inBbox(world.bbox, el.lat, el.lon)) continue;
        const l = frame.geoToLocal(el.lat, el.lon);
        pois.push({
          id,
          pos: [round2(l.x), round2(l.z)],
          geo: { lat: el.lat, lon: el.lon },
          name: tags.name ?? null,
          brand: tags.brand ?? null,
          category: tags.shop ?? tags.amenity ?? tags.tourism ?? tags.office ?? null,
          address: [tags['addr:housenumber'], tags['addr:street']].filter(Boolean).join(' ') || null,
          tags,
        });
      }
    }

    return { buildings, buildingParts, streets, pois };
  },
};

const round2 = (v) => Math.round(v * 100) / 100;

/**
 * Area-weighted centroid of a closed lat/lon ring, computed relative to the first
 * vertex so the shoelace terms do not cancel catastrophically at 8 significant
 * figures of longitude. Degenerate (zero-area) rings fall back to the mean vertex.
 */
function ringCentroid(g) {
  const ox = g[0].lon, oy = g[0].lat;
  let A = 0, cx = 0, cy = 0;
  for (let i = 0; i < g.length - 1; i++) {
    const x0 = g[i].lon - ox, y0 = g[i].lat - oy;
    const x1 = g[i + 1].lon - ox, y1 = g[i + 1].lat - oy;
    const c = x0 * y1 - x1 * y0;
    A += c; cx += (x0 + x1) * c; cy += (y0 + y1) * c;
  }
  if (Math.abs(A) < 1e-16) {
    return {
      lat: g.reduce((s, p) => s + p.lat, 0) / g.length,
      lon: g.reduce((s, p) => s + p.lon, 0) / g.length,
    };
  }
  A /= 2;
  return { lat: oy + cy / (6 * A), lon: ox + cx / (6 * A) };
}
